if(i == 1 || j == 1 || i == j) continue;
draw(P[i]--Pp[j]); draw(Pp[i]--P[j]);
}
dot(P[i]); dot(Pp[i]);
dot(pt(i)); dot(ptp(i));
}

label("$P_1$", P[1], dir(P[1]));
label("$P_2$", P[2], dir(P[2]));
label("$P_3$", P[3], dir(-45));
label("$P_4$", P[4], dir(P[4]));
label("$P'_1$", Pp[1], dir(Pp[1]));
label("$P'_2$", Pp[2], dir(Pp[2]));
